// Subject routing keeps original Czech storage keys and isolates mathematics.
let appSubject='czech',mathCatalog=null,mathLoadError=null;
let cermatSubjectEpoch=0,cermatStartToken=0,cermatInitPromise=null,cermatReviewIndex=0;
try{if(localStorage.getItem('lz-subject')==='math')appSubject='math'}catch{}
const mathCategories=[['Čísla a výpočty','½','Zlomky, výrazy a početní operace','#edd2c0','#19454b'],['Vztahy a data','%','Rovnice, poměr, procenta a slovní úlohy','#e0ebe5','#19454b'],['Geometrie','△','Úhly, obsahy, objemy a konstrukce','#f3e2d6','#19454b'],['Logické úlohy','?','Pravidelnosti a hledání souvislostí','#edd2c0','#19454b']];
function subjectCategories(){return appSubject==='math'?mathCategories:categories}
function subjectCatalog(){return appSubject==='math'?mathCatalog:cermatCatalog}
function subjectName(){return appSubject==='math'?'Matematika':'Čeština'}
function subjectStorage(key){return appSubject==='math'?'lz-math-'+key:key}
function subjectSwitch(){return `<div class="subject-switch" role="group" aria-label="Vyber předmět"><button data-subject="czech" aria-pressed="${appSubject==='czech'}" class="${appSubject==='czech'?'selected':''}"><span>Čj</span>Čeština</button><button data-subject="math" aria-pressed="${appSubject==='math'}" class="${appSubject==='math'?'selected':''}"><span>∑</span>Matematika</button></div>`}
function setSubject(value,fromHistory=false){if(!['czech','math'].includes(value)||value===appSubject)return;save();document.getElementById('dialog')?.close();appSubject=value;cermatSubjectEpoch++;cermatStartToken++;cermatBusy=false;try{localStorage.setItem('lz-subject',value)}catch{}db=read(subjectStorage('cnt-data-v1'),{history:[],mistakes:[],attempts:{}});session=read(subjectStorage('cnt-session-v1'),null);reviewResult=null;if(fromHistory)return;try{window.history.pushState({cntPage:'home',cntSubject:appSubject},'')}catch{}navigate('home',true);if(session){const active=session,epoch=cermatSubjectEpoch;cermatEnsure(active.ids).then(()=>{if(epoch!==cermatSubjectEpoch||session!==active)return;tick();if(page==='home')render()}).catch(e=>{if(epoch===cermatSubjectEpoch)toast(e.message)})}}
function mathImageBind(){document.querySelectorAll('[data-math-image]').forEach(el=>el.onclick=()=>{const src=el.dataset.mathImage;if(!/^math\/images\/[A-Z0-9_]+\.webp$/.test(src))return;const d=document.getElementById('dialog');d.innerHTML=`<div class="math-image-dialog"><button class="btn secondary" id="close-math-image">Zavřít zvětšení</button><p>Obrázek můžeš posouvat do stran. Řešení se otevírá až po kontrole nebo odevzdání.</p><div class="math-image-pan"><img src="${src}" alt="Zvětšený podklad CERMAT"></div></div>`;d.classList.add('math-image-modal');d.showModal();d.querySelector('#close-math-image').onclick=()=>d.close();d.addEventListener('close',()=>d.classList.remove('math-image-modal'),{once:true})})}
function mathAboutView(){const c=mathCatalog,ts=c?.tests||[];return `<div class="intro"><div><div class="eyebrow">Matematika · průhledné podklady</div><h1>Vypočítej. Pochop. Zkus znovu.</h1></div></div><div class="card method"><h2>Oficiální zadání, klíče a bodování</h2><p>Aktivní banka obsahuje ${ts.reduce((n,t)=>n+t.count,0)} celých úloh z ${ts.length} testů CERMAT pro čtyřleté obory a šestiletá gymnázia. Banka pokrývá roky ${c?.coverage.years.join(', ')}. Pro oba obory jsou zahrnuté řádné a náhradní termíny 2019–2026, zveřejněné ilustrační testy 2019–2021 a pro čtyřleté obory také Přijímačky nanečisto 2025 a 2026. V roce 2020 se konal jeden řádný a jeden náhradní termín. Šest starších náhradních testů 2019/2020 pochází z archivních kopií původních materiálů CERMAT na StátníPřijímačky.cz.</p><p>Vzorce, obrázky i řešení zachovávají původní sazbu CERMAT. Zvětšení otevře podklad přímo zde, bez PDF a bez nové stránky. Při práci si připrav papír a rýsovací potřeby. Konstrukční úlohy řeš na papíře podle podkladu; aplikace nenahrazuje pravítko a kružítko.</p><h2>Klíč a vzorový postup jsou různé podklady</h2><p>Správné odpovědi a konkrétní pravidla dílčích bodů jsou připojené ke každé úloze. Připojená vzorová řešení CERMAT jsou dostupná přímo zde. U roku 2026 lze rozbalit správně vyplněný záznamový arch. Pokud je dostupný jen klíč, aplikace ho neoznačuje za výpočet krok za krokem ani za nové autorské vysvětlení.</p><h2>Body odpovídají původnímu klíči</h2><p>Výběr možnosti, ANO/NE a přiřazování hodnotí aplikace automaticky podle klíče a konkrétního bodovacího schématu. Otevřené odpovědi a konstrukce porovnáš s oficiálním klíčem, jeho kritérii a dostupným vzorovým postupem a sám přidělíš povolený počet bodů. U úloh požadujících postup nestačí jen správné číslo. Dokud vlastní kontrolu nedokončíš, výsledek je neúplný.</p><h2>Namíchaný test</h2><p>16 celých úloh, 50 bodů, standardně 70 minut. Sestava zachovává oblasti, typy a maxima podle konkrétního zdrojového testu; vybírá z více zadání a roků. Jedna celá úloha může mít několik dílčích částí. Počet originálních čísel v obrázcích se může lišit od pořadí v namíchaném testu. Nová sestava není oficiálním testem ani kalibrovanou predikcí přijetí.</p><h2>Obsah aktuální banky</h2><div class="tablewrap"><table><thead><tr><th>Obor</th><th>Rok</th><th>Zdroj</th><th>Úloh</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${t.level}leté</td><td>${t.year}</td><td>${E(t.sourceLabel)}</td><td>${t.count}</td></tr>`).join('')}</tbody></table></div><p><a href="https://procvicprijimacky.cermat.cz/" target="_blank" rel="noopener">Oficiální procvičovací banka CERMAT ↗</a></p><p>Podklady a matematická řešení jsou CERMATu; aplikace je nepřipisuje sobě. Metadata a bodovací schémata byla převzata a technicky porovnána se zdrojem. Neproběhla nezávislá učitelská revize každého řešení. Přístup webu zůstává soukromý pro vlastníka.</p><h2>Tvůj pokrok</h2><p>Čeština a matematika mají oddělené pokusy, chyby i rozpracovanou práci. Uložení platí pro tento prohlížeč, bez přenosu na jiné zařízení. Vymazáním dat prohlížeče se pokrok smaže. Čas testu běží i při přepnutí předmětu; po návratu se vypršelý test odevzdá.</p><button class="textlink" data-delete>Smazat můj pokrok v matematice</button></div>`}
function cermatIllustration(name,classes='',loading='lazy'){return `<img class="undraw-art ${classes}" src="illustrations/${name}.svg" alt="" aria-hidden="true" loading="${loading}" decoding="async" width="320" height="240">`}
function cermatCalmArt(){return cermatIllustration(appSubject==='math'?'mathematics':'reading','welcome-illustration','eager')}
// Original task bank. Source PDFs and marking schemes remain attributable to CERMAT.
let cermatCatalog=null,cermatBank={},cermatLoadedTests=new Set(),cermatRequests={},cermatError=null,cermatBusy=false;
let cermatPrefs={level:4};try{const previous=JSON.parse(localStorage.getItem('cnt-cermat-prefs')||'{}');if([4,6].includes(Number(previous.level)))cermatPrefs.level=Number(previous.level)}catch{}
const cermatKind={regular:'Řádný termín',replacement:'Náhradní termín',illustrative:'Ilustrační test',mock:'Přijímačky nanečisto'};
function cermatTestName(t){if(t.kind==='worksheet')return 'ČT edu · '+t.title;if(t.kind==='authored')return 'Autorské procvičování · '+t.title;return `${t.year} · ${t.kind==='illustrative'?'Ilustrační test':t.kind==='mock'?'Přijímačky nanečisto':t.term+'. '+cermatKind[t.kind].toLocaleLowerCase('cs')}`}
function cermatCollections(){const c=subjectCatalog();return [...(c?.tests||[]),...(c?.authored||[]),...(c?.worksheets||[])]}
function cermatTestById(id){return [...(cermatCatalog?.tests||[]),...(cermatCatalog?.authored||[]),...(cermatCatalog?.worksheets||[]),...(cermatCatalog?.archivedAuthored||[]),...(mathCatalog?.tests||[])].find(t=>t.id===id)}
function cermatLevelName(level){return level===4?'Čtyřleté obory · 9. třída':'Šestiletá gymnázia · 7. třída'}
function cermatSavePrefs(){try{localStorage.setItem('cnt-cermat-prefs',JSON.stringify(cermatPrefs))}catch{}}
async function cermatFetchJson(url){const controller=typeof AbortController==='function'?new AbortController():null;const timeout=controller?setTimeout(()=>controller.abort(),20000):null;try{const response=await fetch(url,controller?{signal:controller.signal}:{});if(!response.ok)throw Error('Podklady se nepodařilo načíst. Zkontroluj připojení a zkus to znovu.');return await response.json()}catch(error){if(error.name==='AbortError')throw Error('Načítání trvá příliš dlouho. Zkus to znovu na stabilnějším připojení.');throw error}finally{if(timeout)clearTimeout(timeout)}}
async function cermatInit(){if(cermatInitPromise)return cermatInitPromise;cermatInitPromise=(async()=>{const load=async(subject,url)=>{try{const data=await cermatFetchJson(url);if(subject==='math'){mathCatalog=data;mathLoadError=null}else{cermatCatalog=data;cermatError=null}for(const t of [...(data.tests||[]),...(data.authored||[]),...(data.worksheets||[]),...(data.archivedAuthored||[])]){if(cermatLoadedTests.has(t.id))continue;for(const q of t.questions)cermatBank[q.id]={...q,testId:t.id,level:t.level,year:t.year,kind:t.kind,term:t.term,cermat:true}}}catch(error){if(subject==='math')mathLoadError=error.message;else cermatError=error.message}if(appSubject===subject)render()};await Promise.all([load('czech','cermat/catalog.json'),load('math','math/catalog.json?v=20261025-archive')]);const active=session,epoch=cermatSubjectEpoch;try{if(subjectCatalog()&&active?.ids.some(id=>typeof id==='string'))await cermatEnsure(active.ids)}catch(error){if(epoch===cermatSubjectEpoch)toast(error.message)}if(epoch===cermatSubjectEpoch){render();tick()}})().finally(()=>{cermatInitPromise=null});return cermatInitPromise}
async function cermatLoadTest(id){if(cermatLoadedTests.has(id))return;if(cermatRequests[id])return cermatRequests[id];cermatRequests[id]=(async()=>{const data=await cermatFetchJson(`${id.startsWith('m')?'math':'cermat'}/${id.startsWith('cw-')?'worksheets':id.startsWith('ca-')?'authored':'tests'}/${id}.json`);for(const q of data.questions)cermatBank[q.id]={...q,cermat:true};cermatLoadedTests.add(id)})().finally(()=>delete cermatRequests[id]);return cermatRequests[id]}
async function cermatEnsure(ids){const tests=[...new Set(ids.filter(id=>typeof id==='string').map(id=>id.replace(/-q\d+$/,'')))];await Promise.all(tests.map(cermatLoadTest))}
function cermatActiveMistakeIds(){const active=new Set(cermatPool().map(q=>q.id));return db.mistakes.filter(id=>active.has(id))}
function cermatPool(cat='all'){if(!subjectCatalog())return [];return cermatCollections().filter(t=>t.level===Number(cermatPrefs.level)).flatMap(t=>t.questions).filter(q=>cat==='all'||q.cat===cat)}

function cermatLevelSwitch(){return `<div class="levelswitch" role="group" aria-label="Zvol obor"><button data-level="4" aria-pressed="${Number(cermatPrefs.level)===4}" class="${Number(cermatPrefs.level)===4?'selected':''}">Čtyřleté obory <small>z 9. třídy</small></button><button data-level="6" aria-pressed="${Number(cermatPrefs.level)===6}" class="${Number(cermatPrefs.level)===6?'selected':''}">Šestiletá gymnázia <small>ze 7. třídy</small></button></div>`}

function cermatBankNote(){if(appSubject==='math')return `<p class="bank-note"><b>${mathCatalog?.coverage.activeTasks||0} úloh z ${mathCatalog?.coverage.activeTests||0} testů CERMAT</b><span>2019–2026 · klíče a bodování přímo zde · oba obory</span></p>`;const original=cermatCatalog.tests.reduce((n,t)=>n+t.count,0),added=(cermatCatalog.authored||[]).reduce((n,t)=>n+t.count,0),sheets=(cermatCatalog.worksheets||[]).reduce((n,t)=>n+t.count,0);return added||sheets?`<p class="bank-note"><b>${(original+added+sheets).toLocaleString('cs-CZ')} úloh</b><span>${original.toLocaleString('cs-CZ')} CERMAT + ${added.toLocaleString('cs-CZ')} autorských${sheets?' + '+sheets+' z pracovních listů':''} · oba obory</span></p>`:''}

function cermatTopicCards(){const pool=cermatPool();return `<div class="topics">${subjectCategories().map(([cat,sign,sub,tone,ink])=>{const qs=pool.filter(q=>q.cat===cat),a=qs.filter(q=>db.attempts[q.id]),sum=a.reduce((s,q)=>s+db.attempts[q.id].points,0),max=a.reduce((s,q)=>s+q.max,0);return `<button class="topic" data-practice="${cat}" style="--tone:${tone};--toneInk:${ink}" ${!qs.length?'disabled':''}><div class="topichead"><span class="topicicon">${E(sign)}</span>${I('arrow')}</div><h3>${cat}</h3><p>${sub}</p><div class="topicfoot"><span>${max?Math.round(sum/max*100)+' % naposledy':appSubject==='math'?qs.length+' dostupných úloh':'5 · 10 · 15 · 20 úloh'}</span></div></button>`}).join('')}</div>`}

function cermatPracticeView(){if(!subjectCatalog())return `<div class="card empty"><h2>${(appSubject==='math'?mathLoadError:cermatError)?'Úlohy se nenačetly.':'Připravuji tvoje procvičování…'}</h2><p>${E((appSubject==='math'?mathLoadError:cermatError)||'Za chvíli si vybereš oblast a délku tréninku.')}</p><button class="btn" id="bank-reload">Zkusit znovu</button></div>`;return `<div class="intro illustrated-intro"><div><div class="eyebrow">Krátký trénink · vlastním tempem</div><h1>Co si dnes procvičíš?</h1><p>Vyber oblast. Pak si dej 5, 10, 15 nebo 20 úloh.</p></div>${cermatIllustration('open-book','intro-illustration')}</div>${restore()}${cermatLevelSwitch()}${cermatBankNote()}${cermatTopicCards()}<div class="card quickmix"><div><span class="testbadge">Trochu od všeho</span><h2>Chci mix oblastí</h2><p>Stejná délka tréninku, pestřejší výběr úloh.</p></div><button class="btn secondary" data-practice="all">Vybrat počet ${I('arrow')}</button></div><p class="help training-note">${appSubject==='math'?'Po každé úloze uvidíš klíč, bodování a dostupné vzorové postupy.':'Po každé úloze uvidíš správné řešení a vysvětlení.'} Otázky ke společnému textu držíme za sebou. Jedna číslovaná úloha může obsahovat více podotázek.</p>`}

function cermatPracticeUnits(cat='all',eligibleIds=null){const allowed=new Set(eligibleIds||cermatPool(cat).map(q=>q.id));return cermatCollections().flatMap(t=>t.mixGroups.map(g=>g.ids.filter(id=>allowed.has(id)))).filter(ids=>ids.length);}
function cermatPracticePlan(units,count){if(!Number.isInteger(count)||count<1)return null;const options=shuffle(units),plans=Array(count+1).fill(null);plans[0]=[];for(const unit of options){for(let n=count;n>=unit.length;n--){if(plans[n]===null&&plans[n-unit.length]!==null)plans[n]=[...plans[n-unit.length],unit];}if(plans[count])break;}return plans[count]?.flat()||null;}
function cermatSessionBlock(q){if(!q.contexts.length&&!q.sharedSourceNums?.length)return [];const t=cermatTestById(q.testId),g=t?.mixGroups.find(g=>g.ids.includes(q.id));return g?session.ids.filter(id=>g.ids.includes(id)):[];}
function cermatBlockNotice(q){const ids=cermatSessionBlock(q);if(ids.length<2)return '';return `<section class="text-block-notice" aria-label="Otázky ke společnému textu"><div><b>Jeden text, ${ids.length} ${ids.length<5?'navazující úlohy':'navazujících úloh'}</b><span>Právě řešíš ${ids.indexOf(q.id)+1}. úlohu tohoto bloku.</span></div><nav aria-label="Přejít na úlohu k tomuto textu">${ids.map(id=>{const index=session.ids.indexOf(id);return `<button data-jump="${index}" ${id===q.id?'aria-current="step"':''} aria-label="Přejít na úlohu ${index+1}">${index+1}</button>`}).join('')}</nav></section>`;}
function cermatNextLabel(q){const next=Q(session.ids[session.index+1]);return next&&cermatSessionBlock(q).includes(next.id)?'Další úloha k textu':'Další úloha';}
function cermatHomeView(){if(!subjectCatalog())return cermatPracticeView();return `<section class="welcome"><div class="welcome-copy"><span class="welcome-tag">Tvoje tempo. Tvoje cesta.</span><h1 class="brand-title">Levou<br><span>zadní.</span></h1><p class="current-subject">${subjectName()} · přijímačky po svém</p><p>Nemusíš umět všechno hned.<br>Dej si pár úloh. Pochop, proč. A zkus další.</p><button class="btn welcome-cta" data-nav="practice">Vybrat oblast ${I('arrow')}</button></div><div class="welcome-art" aria-hidden="true">${cermatCalmArt()}</div><span class="welcome-sticker">Po jedné<br>úloze.</span></section>${restore()}${cermatLevelSwitch()}<section class="mode-grid" aria-label="Vyber způsob přípravy"><button class="mode-card mode-practice" data-nav="practice"><span class="mode-symbol">${I('book')}</span><strong>Procvičit oblast</strong><span>${appSubject==='math'?'Výpočty, vztahy, geometrie a logika. Klíče a dostupné postupy přímo u úloh.':'Pravopis, skladba, porozumění a další oblasti. Po každé úloze vysvětlení.'}</span><span class="mode-bottom"><b>5 / 10 / 15 / 20 úloh</b>${I('arrow')}</span></button><button class="mode-card mode-exam" data-nav="tests"><span class="mode-symbol">${I('clock')}</span><strong>Zkusit celý test</strong><span>Nová sestava napříč databází. Výchozí texty a otázky zůstávají spolu.</span><span class="mode-bottom"><b>${appSubject==='math'?16:Number(cermatPrefs.level)===4?30:28} úloh · 50 bodů · ${appSubject==='math'?70:60} minut</b>${I('arrow')}</span></button></section>${cermatDailyGoal()}${cermatBankNote()}<div class="sectiontitle"><div><h2>Rovnou na tvoji oblast</h2><p>Jedním klepnutím si vybereš délku tréninku.</p></div></div>${cermatTopicCards()}${cermatActiveMistakeIds().length?`<div class="bottomnote">${I('flag')}<div><b>Vrať se k tomu, co ještě nejde.</b><br>V přehledu chyb čekají úlohy z minulých pokusů.</div><button class="textlink" data-nav="mistakes">Moje chyby ${I('arrow')}</button></div>`:''}`;}
function cermatMixedTests(){return (subjectCatalog()?.tests||[]).filter(t=>t.level===Number(cermatPrefs.level))}

function cermatMixedPlan(tests=cermatMixedTests()){
 if(tests.length<2)return null;
 const candidates=[...tests,...(subjectCatalog()?.authored||[]).filter(t=>t.examEligible===true&&tests.some(x=>x.level===t.level))].flatMap(t=>t.mixGroups.filter(g=>t.kind!=='authored'||g.examEligible===true).map(g=>({...g,testId:t.id,year:t.year,authored:t.kind==='authored'})));let best=null;
 for(const template of shuffle(tests)){
  const used=new Set(),sources=new Set(),years=new Set(),chosen=[];
  for(const slot of template.mixGroups){
   const reserved=new Set(template.mixGroups.filter(g=>g!==slot).flatMap(g=>g.ids));
   const matches=shuffle(candidates.filter(g=>g.signature===slot.signature&&(!g.authored||chosen.filter(x=>x.authored).reduce((n,x)=>n+x.ids.length,0)+g.ids.length<=Math.floor(template.count/3))&&!g.ids.some(id=>used.has(id)||reserved.has(id))&&(slot.taskWords===undefined||g.taskWords===undefined||Math.abs(g.taskWords-slot.taskWords)<=Math.max(20,slot.taskWords*.30))&&(slot.words===0?g.words===0:Math.abs(g.words-slot.words)<=Math.max(45,slot.words*.30))));
   matches.sort((a,b)=>(a.year===null||years.has(a.year)?1:0)-(b.year===null||years.has(b.year)?1:0)||(a.testId===template.id)-(b.testId===template.id)||(sources.has(a.testId)?1:0)-(sources.has(b.testId)?1:0));
   const pick=matches[0]||{...slot,testId:template.id,year:template.year};chosen.push(pick);sources.add(pick.testId);if(pick.year!==null)years.add(pick.year);pick.ids.forEach(id=>used.add(id));
  }
  const plan={ids:chosen.flatMap(g=>g.ids),sources:[...sources],years:[...years],blueprint:template.id,max:chosen.reduce((n,g)=>n+g.max,0),words:chosen.reduce((n,g)=>n+g.words,0),baseWords:template.mixGroups.reduce((n,g)=>n+g.words,0)};
  if(!best||Math.min(2,plan.years.length)>Math.min(2,best.years.length)||(Math.min(2,plan.years.length)===Math.min(2,best.years.length)&&plan.sources.length>best.sources.length))best=plan;
  if(plan.sources.length>=Math.min(5,tests.length)&&plan.years.length>=Math.min(2,new Set(tests.map(t=>t.year)).size))break;
 }
 return best?.sources.length>1&&best.years.length>=Math.min(2,new Set(tests.map(t=>t.year)).size)?best:null;
}
function cermatMixedCard(){const count=appSubject==='math'?16:Number(cermatPrefs.level)===4?30:28;return `<div class="card mixedcard exam-start"><div><span class="testbadge">Nová sestava při každém spuštění</span><h2>Celý test nanečisto</h2><div class="chips"><span class="chip">${count} úloh</span><span class="chip">50 bodů</span><span class="chip">${appSubject==='math'?70:60} minut</span></div><p>Úlohy vybíráme napříč databází podle stavby původních testů. Texty i navazující otázky zůstávají pohromadě.</p></div><button class="btn" id="mixed-exam">Sestavit test ${I('arrow')}</button></div>`}

function cermatMixedDialog(){const plan=cermatMixedPlan();if(!plan)return toast('Test se nepodařilo sestavit. Zkus to znovu.');modal(`<div class="eyebrow">${cermatLevelName(Number(cermatPrefs.level))}</div><h2>Připraveno? Dej si prostor.</h2><div class="chips"><span class="chip">${plan.ids.length} úloh</span><span class="chip">50 bodů</span></div><p>Čeká tě nová sestava z různých zadání. Odpovědi můžeš měnit, úlohy si označit a vrátit se k nim. Rozbor a vysvětlení se ukážou až po odevzdání.</p><label for="mixed-time">Kolik času potřebuješ?</label><select id="mixed-time">${[1,1.25,1.5,1.75,2].map((f,i)=>{const n=(appSubject==='math'?70:60)*f;return `<option value="${n}">${n} minut${i?' · +'+i*25+' %':' · běžný limit'}</option>`}).join('')}</select><p class="help">Čas běží i po opuštění stránky. Po vypršení se test odevzdá automaticky.</p>${session?'<p><b>Nový test nahradí rozpracovaný pokus.</b></p>':''}`,'Spustit test',d=>cermatBegin('exam',plan.ids,subjectName()+' · Test nanečisto · '+(Number(cermatPrefs.level)===4?'4leté obory':'6letá gymnázia'),Number(d.querySelector('#mixed-time').value),{mixed:true,mixSources:plan.sources,mixBlueprint:plan.blueprint}))}

function cermatTestsView(){if(!subjectCatalog())return cermatPracticeView();if(appSubject==='math')return `<div class="intro illustrated-intro"><div><div class="eyebrow">Matematika · generálka</div><h1>Vyzkoušej si celý test.</h1><p>Nová sestava, stejné typy a bodování. Připrav si i papír.</p></div>${cermatIllustration('exam-prep','intro-illustration')}</div>${restore()}${cermatLevelSwitch()}${cermatMixedCard()}<div class="card method"><h2>Výsledek i postup</h2><p>Čeká tě 16 celých úloh za 50 bodů a 70 minut. Jedna úloha může mít několik částí. Výběry odpovědí se hodnotí automaticky; výpočty a konstrukce po odevzdání porovnáš s oficiálním postupem. U úloh vyžadujících postup nestačí samotné číslo.</p><p>Zdrojové roky a původní čísla zůstávají v obrázcích. Jde o cvičný mix z databáze 2019–2026, nikoli o nový oficiální test. Shodné typy a body nezaručují totožnou obtížnost ostrého testu.</p></div>`;if(!subjectCatalog())return cermatPracticeView();return `<div class="intro illustrated-intro"><div><div class="eyebrow">Generálka na přijímačky</div><h1>Vyzkoušej si celý test.</h1><p>Ty si vybereš obor. Sestavu úloh připravíme my.</p></div>${cermatIllustration('exam-prep','intro-illustration')}</div>${restore()}${cermatLevelSwitch()}${cermatMixedCard()}<div class="exam-steps"><div><span>01</span><h3>Jako u přijímaček</h3><p>Rozsah, typy úloh a bodové rozložení podle původních testů.</p></div><div><span>02</span><h3>Všechno na jednom místě</h3><p>Výchozí texty, otázky i odpovědi řešíš přímo v aplikaci.</p></div><div><span>03</span><h3>Rozbor po odevzdání</h3><p>Body, správné odpovědi a vysvětlení ti ukážou, co procvičit dál.</p></div></div><p class="help training-note">Jde o cvičnou sestavu z původních úloh CERMAT a zkontrolovaných autorských bloků stejného typu, bodování a podobné délky. Autorské úlohy mohou tvořit nejvýše třetinu sestavy. Stejné bodování a struktura nezaručují totožnou obtížnost s konkrétním ostrým testem. Tvořené otevřené odpovědi po odevzdání posoudíš podle klíče.</p>`}

function cermatProgressView(){const all=[...questions,...Object.values(cermatBank)];return `<div class="intro illustrated-intro"><div><div class="eyebrow">Tvůj vlastní přehled</div><h1>Každý pokus se počítá.</h1><p>Úspěšnost počítáme z přidělených bodů. Otevřené úlohy čekající na kontrolu do ní zatím nevstupují.</p></div>${cermatIllustration('progress-tracking','intro-illustration')}</div>${!db.history.length?'<div class="card empty"><h2>První výsledek čeká na tebe.</h2><p>Vyber oblast a počet úloh. Výsledek dokončeného tréninku pak najdeš tady.</p><button class="btn" data-nav="practice">Vybrat trénink '+I('arrow')+'</button></div>':`<div class="card"><h2>Poslední výsledky podle oblastí</h2><div class="topicstats">${subjectCategories().map(([cat])=>{let qs=all.filter(q=>q.cat===cat&&db.attempts[q.id]),p=qs.reduce((s,q)=>s+db.attempts[q.id].points,0),m=qs.reduce((s,q)=>s+q.max,0);return `<div class="topicstat"><span>${cat}</span><div class="progress"><div style="width:${m?p/m*100:0}%"></div></div><b>${m?Math.round(p/m*100)+' %':'—'}</b></div>`}).join('')}</div></div><div class="card"><h2>Dokončené pokusy</h2>${db.history.map(r=>{const pend=r.rows.filter(row=>row.points===null).length;return `<div class="historyitem"><div>${E(r.label)}<small>${new Date(r.date).toLocaleString('cs-CZ')} · ${r.rows.length} úloh${pend?' · '+pend+' ke kontrole':''}</small></div><b>${r.rows.reduce((s,x)=>s+(x.points||0),0)}/${maxPoints(r.rows.map(x=>x.id))}${pend?' + ?':''}</b><button class="textlink" data-result="${r.uid}">Rozbor ${I('arrow')}</button></div>`}).join('')}</div><button class="textlink" data-delete>Smazat můj pokrok na tomto zařízení</button>`}`}
function cermatRubric(q){if(q.subject==='math')return q.keyBody;if(q.origin==='worksheet')return 'Otevřená úloha: 1 cvičný bod za slovo splňující všechny podmínky. Po porovnání s příklady přidělíš body vlastní kontrolou.';if(q.type==='manual')return 'Vlastní kontrola podle původního klíče. Nejprve napiš odpověď; řešení otevři až potom.';if(q.type==='choice')return `${q.max} bod za správnou možnost, jinak 0.`;if(q.type==='set')return `Maximum ${q.max} b. Za každý chybějící nebo nadbytečný údaj se odečte 1 bod; nejméně 0. Údaje odděluj čárkami.`;if(q.type==='order')return `Celé správné pořadí = ${q.max} b. Jakákoli chyba = 0 b.`;if(q.type==='bool')return q.keyBody||'Čtyři správné podúlohy = 2 b., tři = 1 b., jinak 0 b.';return q.keyBody||'1 bod za každé správné přiřazení.'}
function cermatScore(q,a){if(q.subject==='math'){if(q.type==='manual')return (q.allowedScores||[0]).includes(a?.selfScore)?a.selfScore:0;if(q.type==='choice')return a===q.key?q.max:0;const n=q.key.filter((v,i)=>v===a?.[i]).length;return q.mathScoreMap[n]??0;}if(q.type==='manual')return a?.selfScore===undefined?0:Number(a.selfScore);if(q.type==='choice')return a===q.key?q.max:0;if(q.type==='order')return q.key.every((v,i)=>v===a?.[i])?q.max:0;if(q.type==='match')return q.key.filter((v,i)=>v===a?.[i]).length;if(q.type==='bool'){const n=q.key.filter((v,i)=>v===a?.[i]).length;const map={};for(const m of q.keyBody.matchAll(/(\d+)\s*podúloh[ay]?\s*(\d+)\s*b\./g))map[Number(m[1])]=Number(m[2]);return map[n]??Math.max(0,n-(q.key.length-q.max))}if(q.type==='set'){const sn=v=>String(v??'').normalize('NFC').trim().replace(/\s+/g,' '),aliases=(q.keyAliases||q.key.map(v=>[v])).map(v=>v.map(sn)),arr=String(a??'').split(/[,;\n]+/).map(sn).filter(Boolean),canonical=arr.map(v=>aliases.findIndex(aa=>aa.includes(v))),missing=aliases.filter((_,i)=>!canonical.includes(i)).length,extra=canonical.filter((v,i)=>v<0||canonical.indexOf(v)!==i).length;return Math.max(0,q.max-missing-extra)}return 0}
function cermatCorrect(q){if(q.type==='manual')return q.subs.length?q.subs.map(s=>s.label+': '+s.answer).join('\n'):q.keyText;if(q.type==='bool')return q.key.map((v,i)=>`${q.labels[i]} ${v==='A'?'ANO':'NE'}`).join(' · ');if(q.type==='order')return q.key.join(' → ');if(q.type==='match')return q.key.map((v,i)=>`${q.labels[i]} ${v}`).join(' · ');return Array.isArray(q.key)?q.key.join(', '):q.key}
function cermatAnswered(q,a){if(q.type==='manual')return !!a?.text?.trim();if(q.type==='choice'||q.type==='set')return !!String(a??'').trim();return Array.isArray(a)&&a.some(Boolean)}
function cermatComplete(q,a){if(q.type==='manual'||q.type==='choice'||q.type==='set')return cermatAnswered(q,a);return q.key.every((_,i)=>!!a?.[i])}
function cermatRegions(regs,label){return regs.map((r,i)=>`<svg class="pdf-region" viewBox="${r.x} ${r.y} ${r.w} ${r.h}" role="img" aria-label="${E(label)}${regs.length>1?', část '+(i+1):''}"><image href="${r.src}" x="0" y="0" width="${r.width}" height="${r.height}"/></svg>`).join('')}
function cermatFragment(html,regs,label,readerHtml=html){if(!regs?.length)return `<div class="fragment"><div class="pdf-text reader-content">${readerHtml}</div></div>`;return `<div class="fragment"><div class="readermodes" role="group" aria-label="Zobrazení ${E(label)}"><button class="selected" data-reader="text">Čitelné zobrazení</button><button data-reader="original">Původní sazba</button></div><div class="pdf-text reader-content">${readerHtml}</div><div class="pdf-original" hidden><div class="pdf-scroll"><div class="pdf-zoom">${cermatRegions(regs,label)}</div></div><label class="zoomlabel">Zvětšení <input type="range" min="100" max="250" value="100" step="25" data-zoom aria-label="Zvětšit původní zadání"></label></div></div>`}
function cermatLanguageSources(q){return q.languageSources?.length?`<section class="language-sources"><h4>Opora v jazykové příručce</h4><p>Odkazy dokládají pravidlo nebo slovníkové heslo. Použití na nové zadání a klíč je výkladem aplikace.</p>${q.languageSources.filter(x=>/^https:\/\/(?:[a-z0-9-]+\.)?ujc\.cas\.cz(?:\/|$)/i.test(x.url)).map(x=>`<a href="${E(x.url)}" target="_blank" rel="noopener">${E(x.title)} ↗</a>`).join('')}</section>`:''}
function cermatDailyGoal(){const today=new Date().toLocaleDateString('cs-CZ'),ids=new Set(db.history.filter(h=>new Date(h.date).toLocaleDateString('cs-CZ')===today).flatMap(h=>h.rows.filter(r=>r.points!==null).map(r=>r.id))),n=Math.min(5,ids.size);return `<section class="daily-goal" aria-label="Dnešní malý cíl"><div><b>${n===5?'Dnešní pětka hotová.':'Dnes stačí pět.'}</b><p>${n===5?'Další úlohy už jsou bonus. Vyber si, na co máš chuť.':'Pět úloh v dokončeném tréninku. I chyba se počítá, když pochopíš proč.'}</p></div><span class="goal-count">${n}<small>/ 5</small></span><div class="goal-track" role="progressbar" aria-label="Dnešní zkontrolované úlohy" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${n}"><span style="width:${n*20}%"></span></div></section>`}
function cermatKeyView(q){if(q.subject==='math')return `<div class="keyview"><h3>Řešení a postup</h3><section class="solution-answer"><h4>Správná odpověď a bodování CERMAT</h4>${q.readerAnswerHtml}</section><section class="solution-reason"><h4>${q.explanation.kind==='worked'?'Oficiální vzorové řešení':q.explanation.kind==='filled'?'Ukázka vyplněného archu CERMAT':q.explanation.kind==='document'?'Vzorové řešení CERMAT':'Dostupnost podrobného postupu'}</h4>${q.explanation.readerHtml}</section><p class="rule">${E(q.keyBody)}</p><p class="help">${q.type==='manual'?'Otevřenou odpověď zkontroluj podle celého postupu a přiděl povolený počet bodů. Konstrukci porovnej na papíře.':'Body přiděluje aplikace podle oficiálního klíče.'}</p></div>`;const explanation=q.explanation,option=q.type==='choice'?cermatOption(q,q.key):'';return `<div class="keyview"><h3>Řešení a vysvětlení</h3><section class="solution-answer"><div class="eyebrow">Správná odpověď · ${q.origin==='worksheet'?'příklady z klíče ČT edu':q.origin==='authored'?'autorský klíč':'klíč CERMAT'}</div><div class="key-readable">${q.readerAnswerHtml||`<p>${E(cermatCorrect(q))}</p>`}${option?`<p>${E(option)}</p>`:''}</div></section>${explanation?`<section class="solution-reason"><h4>${explanation.kind==='comment'?'Proč je to tak':'Ukázkové řešení'}</h4><span class="explain-source">${explanation.kind==='comment'?'Komentář CERMAT':'Řešení CERMAT'}${explanation.reused?' · shodné zadání':''}</span><div class="explain-body official-comment">${explanation.readerHtml||explanation.html}</div>${explanation.evidenceHtml?`<details class="explain-evidence"><summary>Pasáže, o které se vysvětlení opírá</summary><div class="explain-body source-evidence">${explanation.evidenceReaderHtml||explanation.evidenceHtml}</div></details>`:''}</section>`:''}${!explanation||explanation.kind==='solution'?`<section class="solution-reason"><h4>${q.teaching?'Proč je to tak':'Jak řešení ověřit'}</h4><span class="explain-source author">Výklad aplikace</span>${cermatTeaching(q)}</section>`:''}${cermatLanguageSources(q)}<section class="solution-marking"><h4>Jak se přidělují body</h4><div class="key-rubric">${q.readerRubricHtml||`<p>${E(q.keyBody||cermatRubric(q))}</p>`}</div></section>${q.keyRegions?.length?`<details class="key-original"><summary>${q.origin==='worksheet'?'Původní řešení pracovního listu':'Původní tabulka klíče přímo zde'}</summary><div class="pdf-scroll"><div class="pdf-zoom">${cermatRegions(q.keyRegions,'Původní bodování k úloze '+q.num)}</div></div></details>`:''}</div>`}

// Use only complete parsed sets. If a source has an unusual layout, retain the entire
// original readable content and fall back to its labelled answer controls.
function cermatInlineParts(q){const html=q.readerHtml||q.html||'',kind=q.type==='choice'?'reader-option':['bool','match'].includes(q.type)?'reader-item':null;if(!kind)return {html,items:[]};const items=[...html.matchAll(new RegExp('<p class="'+kind+'">([\\s\\S]*?)</p>','g'))];const count=q.type==='choice'?q.letters.length:q.labels.length;if(items.length!==count)return {html,items:[]};if(q.type==='choice'&&!items.every((m,i)=>new RegExp('>'+q.letters[i]+'\\)').test(m[1])))return {html,items:[]};return {html:html.replace(new RegExp('<p class="'+kind+'">[\\s\\S]*?</p>','g'),''),items:items.map(m=>m[1])}}
function cermatInput(q,a,checked){const dis=checked?'disabled':'',parts=cermatInlineParts(q);if(q.type==='manual')return `<div class="field answers"><label for="manual-answer">${q.origin==='worksheet'?'Napiš jedno slovo odpovídající zadání':'Tvoje odpověď · rozliš dílčí otázky jejich číslem'}</label><textarea id="manual-answer" spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" ${dis}>${E(a?.text||'')}</textarea></div>`;if(q.type==='set')return `<div class="field answers"><label for="setanswer">Tvoje odpověď · slova nebo čísla odděluj čárkami</label><textarea id="setanswer" spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" ${dis}>${E(a||'')}</textarea></div>`;if(q.type==='choice')return `<fieldset class="answers choiceanswers ${parts.items.length?'inline-answers':'letteranswers'}" aria-label="Vyber správnou odpověď">${q.letters.map((v,i)=>`<label class="option"><input type="radio" name="answer" value="${v}" ${a===v?'checked':''} ${dis}><span class="option-copy">${parts.items[i]||E(v)}</span></label>`).join('')}</fieldset>`;if(q.type==='bool')return `<div class="answers">${q.labels.map((label,i)=>`<fieldset class="boolrow"><legend class="statement">${parts.items[i]||E(label)}</legend><div class="boolbuttons">${['A','N'].map(v=>`<label><input type="radio" name="answer${i}" data-slot="${i}" value="${v}" ${a?.[i]===v?'checked':''} ${dis}><span>${v==='A'?'ANO':'NE'}</span></label>`).join('')}</div></fieldset>`).join('')}</div>`;return `<div class="answers">${q.key.map((_,i)=>`<fieldset class="assignment"><legend>${q.type==='order'?(i+1)+'. část v pořadí':parts.items[i]||E(q.labels[i])}</legend><div class="assignment-options">${q.letters.map(v=>`<label title="${E(cermatOption(q,v))}"><input type="radio" name="slot-${i}" data-slot="${i}" value="${v}" ${a?.[i]===v?'checked':''} ${dis}><span>${v}</span></label>`).join('')}</div>${q.type==='match'?`<p class="selection-preview" data-selection-preview="${i}" aria-live="polite">${a?.[i]?E(cermatOption(q,a[i])):''}</p>`:''}</fieldset>`).join('')}</div>`}
function cermatSelfScore(q,value){return `<div class="selfscore"><label for="selfscore"><b>Kolik bodů odpověď získává podle uvedených pravidel?</b></label><p class="help">Porovnej všechny části odpovědi a přiděl body podle zobrazeného pravidla. Kontroluješ se sám; výsledek není automaticky ověřený.</p><select id="selfscore"><option value="">Vyber počet bodů…</option>${(q.allowedScores||Array.from({length:q.max+1},(_,i)=>i)).map(i=>`<option value="${i}" ${String(value)===String(i)?'selected':''}>${i} z ${q.max} bodů</option>`).join('')}</select></div>`}
function cermatSourceBar(q,t){if(q.origin==='worksheet')return `<details class="sourcebar worksheet-source"><summary><span class="author-badge">Pracovní list · ČT edu</span> Původ úlohy</summary><div><span>${E(q.sourceTitle)} · původní č. ${q.num} · ${cermatLevelName(q.level)}</span><p>Zadání a ukázkové odpovědi pocházejí z pracovního listu ČT edu. Vysvětlení doplňuje a věcné chyby původního postupu opravuje aplikace. Bodování 1/0 je cvičné pravidlo aplikace, nikoli bodovací klíč CERMATu.</p><a href="${E(q.sourceUrl)}" target="_blank" rel="noopener">Zdroj pracovního listu ↗</a></div></details>`;if(q.origin==='authored')return `<details class="sourcebar authored-source"><summary><span class="author-badge">Autorská úloha</span> Původ a procvičovaná dovednost</summary><div><span>${E(q.skill)} · ${cermatLevelName(q.level)}</span><p>Nové zadání aplikace podle principů přijímacích úloh. Klíč, bodování a vysvětlení jsou autorské. Nejde o materiál CERMATu. Jazyková opora či důkazy z textu jsou u řešení.</p></div></details>`;return `<details class="sourcebar"><summary>Původ úlohy · CERMAT</summary><div><span>${cermatLevelName(q.level)} · ${cermatTestName(t)} · původní č. ${q.num}</span><a href="${E(q.sourceUrl)}#page=${q.sourcePage||q.regions?.[0]?.page||1}" target="_blank" rel="noopener">Zdrojové zadání ↗</a></div></details>`}
function cermatExercise(){const q=Q(session.ids[session.index]);if(!q.html)return '<div class="card"><h2>Načítám původní zadání…</h2><button class="btn" data-resume>Zkusit znovu</button></div>';const t=cermatTestById(q.testId),a=session.answers[q.id],checked=session.checked.includes(q.id),n=session.ids.filter(id=>complete(Q(id),session.answers[id])).length;return `<div class="sessionbar"><div><small>${session.mode==='exam'?(session.mixed?'NAMÍCHANÝ TEST':'TEST CERMAT'):'PROCVIČOVÁNÍ'} / ${E(session.label)}</small><h1>Úloha ${session.index+1} z ${session.ids.length}</h1></div><div class="sessiontools">${session.mode==='exam'?'<span class="timer" id="timer" aria-label="Zbývající čas">--:--</span>':'<span class="badge">Vlastním tempem</span>'}<button class="btn secondary" id="leave">Uložit a odejít</button></div></div><div class="progress"><div style="width:${n/session.ids.length*100}%"></div></div>${cermatSourceBar(q,t)}${cermatBlockNotice(q)}<div class="exercise ${!q.contexts.length?'no-reading':''}">${q.contexts.length?`<details class="reading original-reading" ${session.collapsedTexts?.includes(q.contexts.map(c=>c.id).join('|'))?'':'open'}><summary>${q.subject==='math'?'Výchozí podklad':'Výchozí text'} <span>Rozbalit / sbalit</span></summary><div class="passage-body"><div class="eyebrow">${q.subject==='math'?'Text, graf nebo obrázek':'Text k otázkám'}</div>${q.contexts.map(c=>`<section>${cermatFragment(c.html,c.regions,'Výchozí text',c.readerHtml)}</section>`).join('')}${q.origin==='authored'?'':'<p class="help">Původní sazba zachovává grafiku a rozmístění. U úloh s vyznačenými slovy ji můžeš kdykoli otevřít.</p>'}</div></details>`:''}<section><div class="qcard"><div class="qmeta"><span>${q.cat}</span>${q.contexts.length?'<button class="textlink" data-show-text>Zpět k textu ↑</button>':''}<b>${q.max} b.</b></div><h2 class="sr-only" id="question-heading" tabindex="-1">${q.origin==='authored'?'Autorská':'Původní'} úloha ${q.num}</h2>${cermatFragment(q.html,q.regions,'Zadání úlohy '+q.num,cermatInlineParts(q).html)}${q.subject==='math'&&q.type==='manual'?'<p class="help math-work-note">Vypočítej na papíře. Sem zapiš odpovědi a případně postup; u konstrukce napiš, že máš narýsováno. Po kontrole porovnáš řešení.</p>':''}${cermatInput(q,a,checked)}<div class="rule">${E(cermatRubric(q))}</div>${checked?`<div class="feedback ${q.type!=='manual'&&cermatScore(q,a)<q.max?'partial':''}">${q.type==='manual'?'<strong>Porovnej svou odpověď s klíčem.</strong>':`<strong>${cermatScore(q,a)===q.max?'Tohle sedí.':'Tady rozhoduje detail.'} ${cermatScore(q,a)}/${q.max} b.</strong><p>Správně: ${E(cermatCorrect(q))}</p>`}${cermatKeyView(q)}${q.type==='manual'?cermatSelfScore(q,a?.selfScore):''}</div>`:''}<div class="qactions"><button class="flag ${session.flags.includes(q.id)?'on':''}" id="flag" aria-pressed="${session.flags.includes(q.id)}">${I('flag')}${session.flags.includes(q.id)?'Označeno':'Označit'}</button>${session.mode==='practice'&&!checked?`<button class="btn dark" id="check" ${cermatComplete(q,a)?'':'disabled'}>${q.type==='manual'?'Zobrazit řešení':'Zkontrolovat'} ${I('check')}</button>`:`<button class="btn" id="next">${session.index===session.ids.length-1?'Dokončit':cermatNextLabel(q)} ${I('arrow')}</button>`}</div></div><nav class="questionnav" aria-label="Úlohy">${session.ids.map((id,i)=>`<button data-jump="${i}" class="${i===session.index?'current ':''}${answered(Q(id),session.answers[id])?'answered ':''}${session.flags.includes(id)?'flagged':''}" aria-label="Úloha ${i+1}" ${i===session.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</nav><div class="sessionfooter"><button class="textlink" id="prev" ${session.index===0?'disabled':''}>${I('back')} Předchozí</button><button class="textlink" id="finish">${session.mode==='exam'?'Odevzdat test':'Dokončit trénink'} ${I('check')}</button><div class="help" id="fillcount">${n}/${session.ids.length} vyplněno · označené úlohy mají žlutou tečku</div></div></section></div>`}
function cermatBindReaders(){document.querySelectorAll('[data-show-text]').forEach(el=>el.onclick=()=>{const reading=document.querySelector('.original-reading');if(reading){reading.open=true;reading.scrollIntoView({block:'start',behavior:'smooth'})}});document.querySelectorAll('[data-reader]').forEach(el=>el.onclick=()=>{const frag=el.closest('.fragment');frag.querySelector('.pdf-text').hidden=el.dataset.reader!=='text';frag.querySelector('.pdf-original').hidden=el.dataset.reader!=='original';frag.querySelectorAll('[data-reader]').forEach(b=>b.classList.toggle('selected',b===el))});document.querySelectorAll('[data-zoom]').forEach(el=>el.oninput=()=>el.closest('.pdf-original').querySelector('.pdf-zoom').style.width=el.value+'%')}
function bindCermatSession(){const q=Q(session.ids[session.index]);if(!q.html)return;const reading=document.querySelector('.original-reading'),readingKey=q.contexts.map(c=>c.id).join('|');if(reading){reading.addEventListener('toggle',()=>{session.collapsedTexts=(session.collapsedTexts||[]).filter(k=>k!==readingKey);if(!reading.open)session.collapsedTexts.push(readingKey);save()});reading.scrollTop=session.readingPositions?.[readingKey]||0;reading.addEventListener('scroll',()=>{session.readingPositions??={};session.readingPositions[readingKey]=reading.scrollTop})}const saveAnswer=el=>{if(session.checked.includes(q.id))return;if(q.type==='manual')session.answers[q.id]={text:el.value};else if(el.dataset.slot!==undefined){if(!Array.isArray(session.answers[q.id]))session.answers[q.id]=[];session.answers[q.id][Number(el.dataset.slot)]=el.value;const preview=document.querySelector(`[data-selection-preview="${el.dataset.slot}"]`);if(preview)preview.textContent=cermatOption(q,el.value)}else session.answers[q.id]=el.value;save();const checkButton=document.getElementById('check');if(checkButton)checkButton.disabled=!complete(q,session.answers[q.id]);const n=session.ids.filter(id=>complete(Q(id),session.answers[id])).length;document.querySelector('.progress div').style.width=n/session.ids.length*100+'%';document.querySelectorAll(`[data-jump="${session.index}"]`).forEach(el=>el.classList.toggle('answered',answered(q,session.answers[q.id])));document.getElementById('fillcount').textContent=`${n}/${session.ids.length} vyplněno · označené úlohy mají žlutou tečku`};document.querySelectorAll('.answers input,.answers textarea,.answers select').forEach(el=>el.addEventListener(el.type==='radio'||el.tagName==='SELECT'?'change':'input',()=>saveAnswer(el)));document.getElementById('flag').onclick=()=>{session.flags=session.flags.includes(q.id)?session.flags.filter(id=>id!==q.id):[...session.flags,q.id];save();render()};document.getElementById('leave').onclick=()=>{save();navigate(session.mode==='exam'?'tests':'practice');toast(session.mode==='exam'?'Uloženo. Čas testu běží dál.':'Trénink je uložen v tomto prohlížeči.')};document.getElementById('prev').onclick=()=>{if(session.index)moveSession(session.index-1)};document.getElementById('next')?.addEventListener('click',()=>{if(session.index<session.ids.length-1){moveSession(session.index+1)}else finishDialog()});document.getElementById('check')?.addEventListener('click',()=>{if(!complete(q,session.answers[q.id]))return toast('Nejdřív vyplň všechny části této úlohy.');if(duplicate(q,session.answers[q.id]))return toast('Každé písmeno použij pouze jednou.');session.checked.push(q.id);save();render();revealFeedback()});document.getElementById('selfscore')?.addEventListener('change',el=>{if(el.target.value==='')delete session.answers[q.id].selfScore;else session.answers[q.id].selfScore=Number(el.target.value);save()});document.getElementById('finish').onclick=finishDialog;tick()}
async function cermatBegin(mode,ids,label,minutes,extra={}){if(cermatBusy)return;const epoch=cermatSubjectEpoch,token=++cermatStartToken,originPage=page,level=cermatPrefs.level,navVersion=appNavigationVersion;cermatBusy=true;toast('Připravuji zadání…');try{await cermatEnsure(ids);if(epoch!==cermatSubjectEpoch||token!==cermatStartToken||page!==originPage||navVersion!==appNavigationVersion||level!==cermatPrefs.level)return;start(mode,ids,label,minutes,extra)}catch(e){if(epoch===cermatSubjectEpoch&&token===cermatStartToken)toast(e.message)}finally{if(token===cermatStartToken)cermatBusy=false}}
function practiceDialog(cat){if(!subjectCatalog())return toast('Úlohy se ještě načítají.');if(cat.startsWith('id:')){const id=cat.slice(3);if(!/^[cm]/.test(id))return toast('Tato ukázková úloha čeká na revizi. Vyber novou úlohu z oblasti.');if(!cermatPool().some(q=>q.id===id))return toast('Tato úloha čeká na revizi. Vyber novou úlohu z oblasti.');return cermatBegin('practice',[id],subjectName()+' · Návrat k úloze')};const pool=cat==='mistakes'?db.mistakes.map(id=>Q(id)).filter(q=>q?.cermat&&cermatPool().some(active=>active.id===q.id)):cermatPool(cat);if(cat==='mistakes'&&!pool.length)return toast('V tomto oboru nemáš aktivní úlohy k opakování.');if(!pool.length)return toast('V této oblasti zatím nejsou dostupné úlohy.');const label=cat==='all'?'Mix oblastí':cat==='mistakes'?'Moje chyby':cat,units=cermatPracticeUnits(cat,pool.map(q=>q.id)),counts=[5,10,15,20].filter(n=>n<=pool.length&&cermatPracticePlan(units,n));if(!counts.length)counts.push(pool.length);modal(`<div class="eyebrow">${cermatLevelName(Number(cermatPrefs.level))} · vlastním tempem</div><h2>${E(label)}</h2><fieldset class="practice-counts"><legend>Kolik úloh si dáš?</legend>${counts.map((n,i)=>`<label><input type="radio" name="practice-count" value="${n}" ${i===0?'checked':''}><span><b>${n}</b><small>úloh</small></span></label>`).join('')}</fieldset><p>Řešení a vysvětlení uvidíš hned po kontrole odpovědi. Můžeš se kdykoli zastavit a pokračovat později.</p>${appSubject==='math'&&pool.length<20?'<p class="help">V této oblasti a oboru je nyní '+pool.length+' celých úloh. Nabízíme jen počty, které lze sestavit bez opakování.</p>':''}<p class="help">${cat==='all'?'Celé bloky se společným textem zůstávají pohromadě.':'Otázky z této oblasti ke společnému textu dostaneš za sebou.'} Počítáme celé úlohy; každá může mít několik podotázek.</p>${session?'<p><b>Nový trénink nahradí rozpracovaný pokus.</b></p>':''}`,'Začít procvičovat',d=>{const n=Number(d.querySelector('input[name="practice-count"]:checked').value),plan=cermatPracticePlan(units,n);if(!plan)return false;cermatBegin('practice',plan,subjectName()+' · '+label+' · '+(Number(cermatPrefs.level)===4?'4leté':'6leté'),null,{topic:cat})})}

function cermatExamDialog(id){const t=cermatCatalog.tests.find(t=>t.id===id);modal(`<div class="eyebrow">${cermatLevelName(t.level)}</div><h2>${cermatTestName(t)}</h2><p>${t.count} úloh, ${t.max} bodů. Čas běží i při opuštění stránky. Řešení uvidíš po odevzdání; tvořené otevřené odpovědi pak porovnáš s původním klíčem.</p><label for="cermat-time">Čas pro tento pokus</label><select id="cermat-time">${[1,1.25,1.5,1.75,2].map((f,i)=>`<option value="${t.minutes*f}">${t.minutes*f} minut · ${i?'+'+(i*25)+' %':'původní limit'}</option>`).join('')}</select>${session?'<p><b>Nový pokus nahradí rozpracovaný pokus.</b></p>':''}`,'Spustit čas a test',d=>cermatBegin('exam',t.questions.map(q=>q.id),cermatTestName(t)+' · '+(t.level===4?'4leté':'6leté'),Number(d.querySelector('#cermat-time').value)))}
function cermatUpdateAttempt(r,date){if(r.points===null||db.attempts[r.id]?.date>date)return;db.attempts[r.id]={points:r.points,date};db.mistakes=db.mistakes.filter(id=>id!==r.id);if(r.points<Q(r.id).max)db.mistakes.push(r.id)}
function cermatSessionReady(s=session){return !!s&&s.ids.every(id=>typeof id!=='string'||!!cermatBank[id]?.html)}
function finalizeCermat(expired){const s=session;if(!s)return;if(!cermatSessionReady(s))return toast('Zadání se ještě načítá. Odpovědi zůstávají uložené.');const result={uid:s.uid,mode:s.mode,label:s.label,date:Date.now(),elapsed:Math.min(Date.now()-s.start,s.deadline?s.deadline-s.start:Infinity),expired,mixed:!!s.mixed,mixSources:s.mixSources||[],answers:s.answers,rows:s.ids.map(id=>{const q=Q(id),a=s.answers[id];return {id,points:q.type==='manual'&&answered(q,a)&&a?.selfScore===undefined?null:score(q,a)}}),cermat:true};if(!db.history.some(h=>h.uid===s.uid)){db.history.unshift(result);db.history=db.history.slice(0,100);for(const row of result.rows)cermatUpdateAttempt(row,result.date)}session=null;reviewResult=result;save();document.getElementById('dialog').close();navigate('result');if(expired)toast('Čas vypršel. Test je odevzdaný; otevřené odpovědi můžeš nyní zkontrolovat.')}
function cermatResultView(r){const pending=r.rows.filter(x=>x.points===null),p=r.rows.reduce((s,x)=>s+(x.points||0),0),m=maxPoints(r.rows.map(x=>x.id)),wrong=r.rows.filter(x=>x.points!==null&&x.points<Q(x.id).max);return `<div class="card resulttop"><div class="eyebrow">${E(r.label)} · Odevzdáno</div><div class="scorecircle"><div>${p}${pending.length?' + ?':''}<small>z ${m} bodů${pending.length?' · neúplné hodnocení':''}</small></div></div><h1>${pending.length?'Ještě zkontroluj otevřené odpovědi.':p===m?'Tohle máš v ruce.':'Teď víš, co procvičit dál.'}</h1><p>${pending.length?`${pending.length} úloh čeká na tvoji kontrolu podle uvedených kritérií. Body v přehledu zatím nejsou konečné.`:`${Math.round(p/m*100)} % bodů · ${wrong.length} úloh k opakování.`}</p>${pending.length?'<button class="btn" id="review-manual">Zkontrolovat otevřené úlohy '+I('arrow')+'</button>':''}${wrong.length?'<button class="btn secondary" data-retry>Procvičit vyhodnocené chyby '+I('arrow')+'</button>':''}<button class="btn secondary" data-nav="practice">Nový trénink</button><p class="help">Automaticky vyhodnocené odpovědi a vlastní hodnocení otevřených úloh se ukládají společně. Výsledek není odhadem přijetí.</p></div><div class="sectiontitle"><h2>Rozbor celého pokusu</h2><span class="help">${new Date(r.date).toLocaleDateString('cs-CZ')}</span></div><div class="review">${r.rows.map(row=>{const q=Q(row.id);return `<details><summary><span>Úloha ${q.num} · ${q.cat} · ${q.origin==='worksheet'?'ČT edu':q.origin==='authored'?'autorská':q.year}</span><b class="${row.points===q.max?'good':row.points===null?'':'wrong'}">${row.points===null?'Ke kontrole':row.points+'/'+q.max+' b.'}</b></summary><div class="detail">${q.html?`${q.contexts.map(c=>`<details><summary>Výchozí text</summary>${cermatFragment(c.html,c.regions,'Výchozí text',c.readerHtml)}</details>`).join('')}${cermatFragment(q.html,q.regions,'Zadání',q.readerHtml)}`:'<p>Zadání se načítá…</p>'}<p><b>Tvoje odpověď:</b> ${E(yourAnswer(q,r.answers[q.id]))}</p>${q.keyRegions?cermatKeyView(q):''}${q.type==='manual'?`<p class="help">${row.points===null?'Body zatím nebyly přiděleny.':'Body byly přiděleny vlastní kontrolou podle klíče.'}</p>`:''}</div></details>`}).join('')}</div>`}
function cermatManualRows(){return reviewResult?.rows.filter(row=>Q(row.id).type==='manual'&&answered(Q(row.id),reviewResult.answers[row.id]))||[]}
function cermatApplyManualGrade(id,value){if(value==='')return false;const row=reviewResult?.rows.find(row=>row.id===id),q=Q(id),points=Number(value),allowed=q.allowedScores||Array.from({length:q.max+1},(_,i)=>i);if(!row||q.type!=='manual'||!allowed.includes(points)||!answered(q,reviewResult.answers[id]))return false;row.points=points;reviewResult.answers[id].selfScore=points;cermatUpdateAttempt(row,reviewResult.date);const saved=db.history.find(item=>item.uid===reviewResult.uid);if(saved)Object.assign(saved,reviewResult);save();return true}
function cermatManualReview(){const r=reviewResult,rows=cermatManualRows();if(!r)return '<div class="card empty"><h2>Vyber nejdřív dokončený pokus.</h2><button class="btn" data-nav="progress">Můj pokrok</button></div>';if(!rows.length)return cermatResultView(r);cermatReviewIndex=Math.max(0,Math.min(cermatReviewIndex,rows.length-1));const row=rows[cermatReviewIndex],q=Q(row.id),graded=rows.filter(item=>item.points!==null).length;return `<div class="intro"><div><div class="eyebrow">Vlastní kontrola · odpověď ${cermatReviewIndex+1} z ${rows.length}</div><h1>Porovnej odpověď, přiděl body.</h1><p id="manual-progress" role="status">Zkontrolováno ${graded} z ${rows.length}. Každé hodnocení se hned ukládá.</p></div></div><div class="card manualcard" data-manual-id="${q.id}"><span class="badge">Úloha ${q.num} · ${q.max} b.</span><details class="review-question"><summary>Zadání a výchozí podklad</summary>${q.contexts.map(c=>cermatFragment(c.html,c.regions,'Výchozí podklad',c.readerHtml)).join('')}${cermatFragment(q.html,q.regions,'Zadání',q.readerHtml)}</details><h2>Tvoje odpověď</h2><div class="qtext">${E(r.answers[q.id]?.text||'')}</div>${cermatKeyView(q)}<label class="field"><b>Body za tuto úlohu</b><select class="manual-grade"><option value="" ${row.points!==null?'disabled':''}>Vyber podle klíče…</option>${(q.allowedScores||Array.from({length:q.max+1},(_,i)=>i)).map(i=>`<option value="${i}" ${row.points===i?'selected':''}>${i} z ${q.max} bodů</option>`).join('')}</select></label><p class="manual-saved help" role="status">${row.points===null?'Tato odpověď ještě čeká na kontrolu.':'Hodnocení je uložené.'}</p></div><div class="manual-actions"><button class="btn secondary" id="manual-prev" ${cermatReviewIndex===0?'disabled':''}>${I('back')} Předchozí</button><button class="btn" id="manual-next" ${row.points===null?'disabled':''}>${cermatReviewIndex===rows.length-1?'Zpět na výsledky':'Další odpověď'} ${I('arrow')}</button></div><button class="textlink" id="save-manual">Dokončit kontrolu později · zpět na výsledky</button>`}
function bindCermat(){cermatBindReaders();mathImageBind();document.querySelectorAll('[data-subject]').forEach(el=>el.onclick=()=>setSubject(el.dataset.subject));document.getElementById('mixed-exam')?.addEventListener('click',cermatMixedDialog);document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>{cermatPrefs.level=Number(el.dataset.level);cermatSavePrefs();render()});document.getElementById('bank-reload')?.addEventListener('click',cermatInit);document.getElementById('review-manual')?.addEventListener('click',()=>{const rows=cermatManualRows();cermatReviewIndex=Math.max(0,rows.findIndex(row=>row.points===null));navigate('manual-review')});document.querySelectorAll('.manual-grade').forEach(el=>el.addEventListener('change',()=>{const card=el.closest('.manualcard');if(!cermatApplyManualGrade(card.dataset.manualId,el.value))return;el.querySelector('option[value=""]')?.setAttribute('disabled','');card.querySelector('.manual-saved').textContent=storageOK?'Hodnocení je uložené.':'Body jsou zatím jen v otevřené kartě. Prohlížeč nedovoluje uložení.';const rows=cermatManualRows();document.getElementById('manual-progress').textContent=`Zkontrolováno ${rows.filter(row=>row.points!==null).length} z ${rows.length}. Každé hodnocení se hned ukládá.`;document.getElementById('manual-next').disabled=false}));document.getElementById('manual-prev')?.addEventListener('click',()=>{if(cermatReviewIndex>0){cermatReviewIndex--;render();window.scrollTo(0,0)}});document.getElementById('manual-next')?.addEventListener('click',()=>{const rows=cermatManualRows();if(rows[cermatReviewIndex]?.points===null)return;if(cermatReviewIndex<rows.length-1){cermatReviewIndex++;render();window.scrollTo(0,0)}else navigate('result')});document.getElementById('save-manual')?.addEventListener('click',()=>navigate('result'))}
async function cermatOpenResult(uid){const epoch=cermatSubjectEpoch,navVersion=appNavigationVersion;try{const r=db.history.find(h=>h.uid===uid);if(!r)return;if(r.rows.some(x=>typeof x.id==='string')){toast('Načítám rozbor…');await cermatEnsure(r.rows.map(x=>x.id))}if(epoch!==cermatSubjectEpoch||navVersion!==appNavigationVersion)return;reviewResult=r;navigate('result')}catch(e){if(epoch===cermatSubjectEpoch)toast(e.message)}}
async function cermatResume(){const active=session,epoch=cermatSubjectEpoch,navVersion=appNavigationVersion;if(!active)return navigate('practice');if(active.ids.some(id=>(cermatCatalog?.archivedAuthored||[]).some(t=>t.questions.some(q=>q.id===id))))return toast('Rozpracovaný pokus obsahuje úlohy čekající na revizi. Vyber nový trénink; uložené výsledky zůstávají.');try{if(active.ids.some(id=>typeof id==='string'))await cermatEnsure(active.ids);if(epoch!==cermatSubjectEpoch||session!==active||navVersion!==appNavigationVersion)return;navigate('session');tick()}catch(e){if(epoch===cermatSubjectEpoch)toast(e.message)}}
function cermatAboutView(){if(appSubject==='math')return mathAboutView();const ts=cermatCatalog?.tests||[],authored=cermatCatalog?.authored||[],authoredCount=authored.reduce((s,t)=>s+t.count,0),worksheetCount=(cermatCatalog?.worksheets||[]).reduce((s,t)=>s+t.count,0),total=ts.reduce((s,t)=>s+t.count,0),auto=ts.reduce((s,t)=>s+t.auto,0)+authored.reduce((s,t)=>s+t.auto,0);return `<div class="intro"><div><div class="eyebrow">Zadání, podklady a pravidla</div><h1>Víš přesně, co procvičuješ.</h1></div></div><div class="card method">${authoredCount?`<h2>${(total+authoredCount+worksheetCount).toLocaleString('cs-CZ')} úloh pro tvoji přípravu</h2><p>${total.toLocaleString('cs-CZ')} původních úloh CERMAT a ${authoredCount.toLocaleString('cs-CZ')} autorských úloh ve stejných sedmi oblastech${worksheetCount?' a '+worksheetCount+' úloh z pracovních listů ČT edu':''}. Autorské úlohy mají nové příklady a texty, vlastní klíč, pravidla bodování a konkrétní vysvětlení. V procvičování se obě části banky míchají; u každého zadání poznáš původ.</p><h2>Autorské úlohy a jejich kontrola</h2><p>Aktivní autorská banka obsahuje ${authoredCount} úloh. Přepracovaná zadání procvičují více jazykových podmínek, korektury textů, přiřazování, přesné výpisy a rozlišování významu, jistoty tvrzení a textové návaznosti. Vzorem byly typy úloh a požadavky v podkladech CERMATu a ČT edu. Texty, otázky, klíče i výklady jsou vlastní. U jazykových úloh jsou odkazy na konkrétní pravidla IJP ÚJČ či slovníková hesla, u čtení a literatury důkazy z výchozího textu. ÚJČ ani CERMAT tyto autorské úlohy neschvalovaly. Proběhla modelová a technická kontrola, nikoli nezávislá učitelská revize nebo měření obtížnosti na žácích. Původní návrhy i historické výsledky jsou zachované. Slabé varianty jsou nahrazované přepracovanými úlohami; nejsou počítané mezi nové kvůli velikosti banky. Do celých testů mohou vstoupit způsobilé celé bloky odpovídající vzoru, nejvýše třetina úloh.</p>`:''}${worksheetCount?`<h2>Pracovní listy ČT edu</h2><p>Ve Slovotvorbě pro čtyřleté obory je ${worksheetCount} úloh z listu Vymýšlení slov podle zadání. Míchají se s ostatními úlohami přímo v tématu Slovotvorba, kde si žák zvolí 5, 10, 15 nebo 20 úloh. Řešení je otevřené: žák kontroluje všechny podmínky a nemusí použít stejný příklad jako klíč. List vlastní bodování neuvádí; aplikace přiděluje vlastní kontrolou 1 bod za splnění všech podmínek, jinak 0. Původní zadání a řešení zůstává dostupné přímo na stránce. Výklad aplikace opravuje zjevné chyby a ukazuje další vyhovující příklady.</p>`:''}<h2>Databáze původních testů CERMAT</h2><p>V aplikaci je ${ts.length} testů a ${total.toLocaleString('cs-CZ')} celých číslovaných úloh za roky 2019–2026: čtyřleté obory (z 9. třídy) a šestiletá gymnázia (ze 7. třídy). Zahrnuté jsou řádné i náhradní termíny, zveřejněné ilustrační testy 2019–2021 a Přijímačky nanečisto 2025 a 2026 pro čtyřleté obory.</p><p>V roce 2020 se konal jeden řádný a jeden náhradní termín. Čtyřleté testy mají 30 úloh, šestileté 28; maximum je u každého testu 50 bodů. Nezaměňujeme počet celých úloh s počtem podotázek.</p><div class="tablewrap"><table><thead><tr><th>Rok</th><th>4leté obory</th><th>6letá gymnázia</th><th>Celkem úloh</th></tr></thead><tbody>${Array.from({length:8},(_,i)=>2026-i).map(y=>{const a=ts.filter(t=>t.year===y);return `<tr><td>${y}</td><td>${a.filter(t=>t.level===4).length} testů</td><td>${a.filter(t=>t.level===6).length} testů</td><td>${a.reduce((s,t)=>s+t.count,0)}</td></tr>`}).join('')}</tbody></table></div><h2>Tematické procvičování</h2><p>Úlohy jsou rozdělené podle hlavní dovednosti do oblastí Pravopis, Porozumění textu, Tvarosloví, Skladba, Slovotvorba, Slovní zásoba a Literatura. Některé úlohy zasahují do více oblastí; ve výběru mají jednu hlavní oblast. Žák volí obor, oblast a dávku 5, 10, 15 nebo 20 číslovaných úloh. Výběr využívá celou databázi napříč roky a termíny. V tematickém tréninku zůstávají vybrané otázky stejné oblasti ke společnému textu za sebou; v mixu oblastí zachováváme celé bloky. V jednom pokusu se úloha neopakuje. Stejný výchozí text může být použit u více různých úloh.</p><p>Původní texty a formulace zadání nejsou obměněné. U originálů je vedle čitelného zobrazení dostupná původní sazba, která zachovává podtržení, tučné písmo, tabulky i obrázky. U každé úlohy je uveden rok, obor, termín a původní číslo. Původní databáze a autorské obměny mají oddělené označení.</p><h2>Namíchaný celý test</h2><p>Aplikace sestavuje cvičné testy z více zadání podle zvoleného oboru; využívá originály CERMATu a způsobilé autorské bloky, jejichž typ, oblast, body a délka odpovídají příslušnému místu ve vzoru. Čtyřleté obory mají 30 úloh, šestiletá gymnázia 28, vždy za 50 bodů. Vzorem je konkrétní původní test: zachovává se pořadí oblastí, typů úloh a bodových maxim. Náhradní bloky mají podobnou délku výchozích textů a společné texty se nerozdělují. Standardní limit je 60 minut s možností navýšení. Nová sestava není oficiálním testem CERMAT a nemusí mít stejnou obtížnost jako vzor.</p><h2>Automatická a vlastní kontrola</h2><p>${auto.toLocaleString('cs-CZ')} úloh má automatickou kontrolu: výběr možnosti, výroky ANO/NE, přiřazování, řazení a jednoznačné výpisy slov nebo čísel. U původních úloh přebíráme bodové maximum a způsob hodnocení z konkrétního klíče. Autorské úlohy mají bodování uvedené ve vlastním klíči. U výpisu odečítáme jak chybějící, tak nadbytečné údaje. U řazení se body přidělují jen za celé správné pořadí.</p><p>Tvořené otevřené odpovědi žák kontroluje podle zobrazených příkladů a kritérií a sám přidělí body. Tím se předejde chybnému odmítnutí správné formulace, kterou automat nezná. V testu se řešení ukáže až po odevzdání. Dokud není otevřená odpověď zkontrolovaná, výsledek je označen jako neúplný a tato úloha se nepočítá do úspěšnosti ani seznamu chyb.</p><p>Automatický import a tematické zařazení prošly technickými kontrolami, nikoli ruční revizí každé jednotlivé úlohy. Při pochybnosti je rozhodující původní test a klíč, dostupné přímo v aplikaci. U otevřené odpovědi požádej o posouzení učitele.</p><h2>Vysvětlení přímo u úloh</h2><p>U zveřejněných komentovaných řešení jsou komentáře CERMAT připojené přímo ke konkrétní úloze. Pokud komentář odkazuje na vyznačené pasáže, lze je rozbalit na stejné stránce. Ukázkové řešení bez zdůvodnění je od komentáře rozlišené. U dalších úloh aplikace doplňuje vlastní zdůvodnění podle zadání a klíče, označené jako výklad aplikace. Jeho autorem není CERMAT. U originálů správné odpovědi a pravidla hodnocení vycházejí z klíče konkrétního testu. Autorské úlohy mají samostatný autorský klíč; není mu připisována autorita CERMATu.</p><h2>Podklady a určení</h2><p>Autorem původních testů a klíčů je Centrum pro zjišťování výsledků vzdělávání (CERMAT). Aplikace není jeho oficiálním produktem. Kopie původních materiálů jsou zde připravené pro neveřejné školní procvičování. Pravidla CERMAT výslovně připouštějí použití při výuce na školách zapsaných v rejstříku MŠMT; další zveřejňování má vlastní podmínky.</p><ul><li><a href="https://prijimacky.cermat.cz/menu/testova-zadani-k-procvicovani/testova-zadani-v-pdf/ctyrlete-obory-cesky-jazyk-a-literatura.html" target="_blank" rel="noopener">CERMAT: čtyřleté obory</a></li><li><a href="https://prijimacky.cermat.cz/menu/testova-zadani-k-procvicovani/testova-zadani-v-pdf/sestilete-obory-cesky-jazyk-a-literatura.html" target="_blank" rel="noopener">CERMAT: šestiletá gymnázia</a></li><li><a href="https://prijimacky.cermat.cz/menu/testova-zadani-k-procvicovani/testova-zadani-v-pdf/prijimacky-nanecisto-zadani-testu.html" target="_blank" rel="noopener">CERMAT: Přijímačky nanečisto</a></li><li><a href="https://prijimacky.cermat.cz/files/files/CZVV_pravidla-vyuziti-webstrankyn.pdf" target="_blank" rel="noopener">CERMAT: pravidla využití materiálů</a></li><li><a href="https://www.statniprijimacky.cz/cestina/ctyrlete-obory/testy-2019" target="_blank" rel="noopener">Archivní kopie náhradních termínů 2019 a 2020: Státní přijímačky / Nový Amos</a></li></ul><p class="help">U každé úlohy je uveden konkrétní zdroj. Řešení, komentáře a bodování se zobrazují přímo na stránce; není nutné otevírat klíč v PDF. Databáze sestavena 21. 10. 2026.</p><h2>Ukládání a soukromí</h2><p>Pokusy, odpovědi a chyby se ukládají jen v tomto prohlížeči, nejvýše posledních 100 pokusů. Nesynchronizují se mezi mobilem, tabletem a počítačem. Na sdíleném školním zařízení mohou zůstat dalšímu uživateli. Aplikace nesbírá jména ani e-maily žáků a nepoužívá analytiku. Písmo Panel Sans se načítá ze služby Adobe Fonts. Přístup k webu zůstává soukromý pro vlastníka.</p><button class="textlink" data-delete>Smazat můj pokrok na tomto zařízení</button></div>`}
function cermatMistakesView(){const ids=cermatActiveMistakeIds();return `<div class="intro illustrated-intro"><div><div class="eyebrow">Chyby jsou vodítko</div><h1>Vrať se k tomu, co ještě nesedí.</h1><p>Úlohy, které jsi naposledy dokončil za méně než plný počet bodů. Nezkontrolované otevřené odpovědi sem nevstupují.</p></div>${cermatIllustration('correct-answer','intro-illustration')}</div>${cermatLevelSwitch()}${ids.length?`<div class="card testcard"><div><h2>${ids.length} úloh k opakování</h2><p>Po správném dokončení dalšího pokusu úloha z tohoto seznamu zmizí.</p></div><button class="btn" data-practice="mistakes">Procvičit chyby ${I('arrow')}</button></div>${ids.map(id=>{const q=Q(id),t=q.cermat?cermatTestById(q.testId):null;return `<div class="card testcard"><div><span class="badge">${q.cat}</span><h3 style="margin-top:10px">${q.origin==='worksheet'?'Pracovní list · úloha '+q.num:q.origin==='authored'?'Autorská úloha '+q.num:q.cermat?'Původní úloha '+q.num:'Autorská úloha '+q.id}</h3><p class="help">${t?`${cermatLevelName(t.level)} · ${cermatTestName(t)}`:'Město a příběhy'}</p></div><button class="btn secondary" data-practice="id:${id}">Zkusit znovu ${I('arrow')}</button></div>`}).join('')}`:'<div class="card empty"><h2>Zatím není co opravovat.</h2><p>Po dokončeném a zkontrolovaném pokusu se sem uloží úlohy, ke kterým má smysl se vrátit.</p><button class="btn" data-nav="practice">Vybrat procvičování '+I('arrow')+'</button></div>'}`}
